async function api(path:string,body?:any,method?:string):Promise<any>{const r=await fetch('/api/'+path,{method:method||(body?'POST':'GET'),...(body?{body:body instanceof FormData?body:JSON.stringify(body),headers:body instanceof FormData?{}:{'Content-Type':'application/json'}}:{})});const d:any=await r.json();if(!r.ok)throw new Error(d.error||'Não foi possível concluir.');return d}
