 async function load(){setLoading(true);setError('');try{const d=await api('state');setMaterials(d.materials);setExams(d.exams);setSessions(d.sessions);setGoals(d.goals||[]);setWeeklyTarget(d.settings?.weeklyTarget||DEFAULT_WEEKLY_TARGET);setAi(d.ai);setSigned(true)}catch(e:any){setError(e.message);if(e.message.includes('Entre com'))setSigned(false)}finally{setLoading(false)}}
