 function fastBanner(){return <section className="fast-banner"><span className="fast-emblem"><Zap size={30} fill="currentColor"/></span><div><span className="fast-label">NOVO · MISSÃO RELÂMPAGO</span><h2>Pouco tempo? Entre no modo Fast.</h2><p>A IA seleciona prioridades. Você aprende jogando, uma pergunta por vez.</p></div><button className="button fast-button" onClick={()=>openFast()}>Ativar Fast <ArrowRight size={17}/></button></section>}
 function start(m:Material,mode:string,questions?:Q[]){if(!m.questions.length&&!questions?.length){setSelected(m);setModal('material');return}setRun({material:m,mode,questions:(questions||m.questions).map(q=>({...q,options:shuffle(q.options)}))});setIndex(0);setAnswers([]);setChoice('');setRevealed(false);setResult(false);setSaveError('');setRewards(null);setModal('');}
